// Invoice ledger (documents/open_invoices.csv)
const inv = {
  'J-4411': {principal: 68400.00, due: '2026-04-30'},
  'J-4452': {principal: 71250.00, due: '2026-05-31'},
  'J-4490': {principal: 66100.00, due: '2026-06-30'},
  'J-4571': {principal: 59450.00, due: '2026-08-31'},
};
// J-4533: gross 74,800 due 2026-07-31; net J-4533R = 71,700 after our $3,100 double-entry credit
const J4533_gross = 74800.00, credit = 3100.00, J4533R = J4533_gross - credit;

const OCT25 = new Date('2026-10-25T00:00:00Z');
const NOV11 = new Date('2026-11-11T00:00:00Z');
const expOct = ['2026-04-30','2026-05-31','2026-06-30','2026-07-31','2026-08-31'].map(d => (OCT25 - new Date(d+'T00:00:00Z'))/86400000);
const expNov = expOct.map(x => x + (NOV11-OCT25)/86400000);
console.log('--- Day counts from due dates to OCT 25 / NOV 11 ---');
console.log('Oct 25:', expOct);   // expect 178, 147, 117, 86, 55
console.log('Nov 11:', expNov);   // expect 195, 164, 134, 103, 72

const r2 = x => Math.round(x*100)/100;
const interest = (p, days) => r2(p * 0.01 * days/30);

console.log('\n--- Oct 25 round (Session 2/3 standing figures) ---');
let octInterest = 0;
for (const [k,v] of Object.entries(inv)) { const i = interest(v.principal, expOct.shift()); octInterest += i; console.log(k, i); }
const j4533_gross_i = interest(J4533_gross, 86), j4533R_i = interest(J4533R, 86);
octInterest += j4533R_i;
console.log('J-4533 gross int', j4533_gross_i, '| J-4533R int', j4533R_i, '| delta (forgone)', r2(j4533_gross_i - j4533R_i));
console.log('Total interest Oct 25 (net):', r2(octInterest));  // expect 13,272.87
const four = Object.entries(inv).reduce((s,[k,v])=>s+v.principal,0);
console.log('Four-invoice principal:', r2(four));              // 265,200
const fourInt_Oct = r2(four*0.01*178/30 + 71250*0.01*147/30 + 66100*0.01*117/30 + 59450*0.01*55/30);
console.log('Four-invoice interest Oct 25:', fourInt_Oct);     // 11,217.47
console.log('Four-invoice block Oct 25:', r2(four + fourInt_Oct)); // 276,417.47
const principalOct = r2(four + J4533R + 80000);
console.log('Principal Oct 25:', principalOct);                // 416,900
console.log('TOTAL Oct 25:', r2(principalOct + octInterest));  // 430,172.87
console.log('Daily rate:', r2((four+J4533R)*0.01/30), '= four', r2(four*0.01/30), '+ J4533R', r2(J4533R*0.01/30)); // 112.30 = 88.40 + 23.90

console.log('\n--- Nov 11 projection (+17 days) ---');
const d17 = r2((four+J4533R)*0.01/30*17);
console.log('17 days of interest:', d17);                      // 1,909.10
const novTotalInt = r2(octInterest + d17);
console.log('Total interest Nov 11:', novTotalInt);            // 15,181.97
const rows = [r2(68400 + interest(68400,195)), r2(71250 + interest(71250,164)), r2(66100 + interest(66100,134)), r2(J4533R + interest(J4533R,103)), r2(59450 + interest(59450,72))];
console.log('Invoice rows at filing:', rows);                   // 72,846 / 75,145 / 69,052.47 / 74,161.70 / 60,876.80
const fourBlockNov = r2(rows[0]+rows[1]+rows[2]+rows[4]);
console.log('Four-invoice block at filing:', fourBlockNov, '(+17x88.40 =', r2(17*four*0.01/30), ')');
console.log('J-4533R at filing:', rows[3], '(+17x23.90 =', r2(17*J4533R*0.01/30), ')');
const invSubtotal = r2(rows.reduce((a,b)=>a+b,0));
console.log('Invoices-only subtotal at filing:', invSubtotal);  // 352,081.97
console.log('GRAND TOTAL at filing:', r2(invSubtotal + 80000)); // 432,081.97
const j4571_nov = r2(59450 + interest(59450,72));
console.log('J-4571 at filing (small-claims check >= 25k):', j4571_nov);

console.log('\n--- Deltas & shares ---');
console.log('Session 1 vs now (Oct 25):', r2(433361.74 - 430172.87)); // 3,188.87 = 3,100 + 88.87
console.log('Check: 3,100 + 88.87 =', r2(3100 + (2144.27-2055.40)));
console.log('CEO 862k vs Oct 25:', r2(862000 - 430172.87));           // 431,827.13
console.log('CEO 862k vs filing proj:', r2(862000 - 432081.97));      // 429,918.03
console.log('Conceded-four share of projection: %', (100*fourBlockNov/432081.97).toFixed(1));
console.log('J-4533R share: %', (100*rows[3]/432081.97).toFixed(1));
console.log('Conversions share: %', (100*80000/432081.97).toFixed(1));
console.log('Invoices-only share: %', (100*invSubtotal/432081.97).toFixed(1));
console.log('Four conceded / interest-bearing principal: %', (100*four/336900).toFixed(1));

console.log('\n--- Conversion scenarios ---');
const threeHires = 3*16000, twoHires = 2*16000;
console.log('Slip on Priya/Luis/Keisha:', threeHires, '-> conversions line', twoHires);
console.log('Scenario B (all invoices + 2-hire conversions):', r2(invSubtotal + twoHires));
console.log('Scenario C (lose J-4533R entirely, all conversions):', r2(invSubtotal - rows[3] + 80000));
console.log('Scenario D (lose J-4533R + slip 3 hires):', r2(fourBlockNov + twoHires));
console.log('Conceded core floor:', fourBlockNov);
console.log('Check B vs projection: -48,000 =', r2(432081.97 - 384081.97));
console.log('Check D vs projection:', r2(432081.97 - 309920.27));

console.log('\n--- CEO reconciliation carried (Session 1 form) ---');
console.log('862,000 - 433,361.74 =', r2(862000 - 433361.74), '(= -410,000 - 32,000 + 13,361.74 + 16,000)');
console.log('Check: ', r2(-410000 - 32000 + 13361.74 + 16000));

console.log('\n--- Rounding sanity on interest rows ---');
console.log('J-4411 @195d:', interest(68400,195), '| J-4452 @164d:', interest(71250,164), '| J-4490 @134d:', interest(66100,134), '| J-4533R @103d:', interest(J4533R,103), '| J-4571 @72d:', interest(59450,72));

